CREATE TYPE public.app_role AS ENUM ('admin','viewer');
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY, role public.app_role NOT NULL);
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_own_role ON public.user_roles FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
CREATE FUNCTION public.is_approved() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = auth.uid()) $$;
CREATE TABLE public.reporting_sources (id text PRIMARY KEY, site text NOT NULL, configuration jsonb NOT NULL DEFAULT '{}', last_success timestamptz, last_error text);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.reporting_sources TO authenticated;
GRANT ALL ON public.reporting_sources TO service_role;
ALTER TABLE public.reporting_sources ENABLE ROW LEVEL SECURITY;
CREATE POLICY source_read ON public.reporting_sources FOR SELECT TO authenticated USING (public.is_approved());
CREATE POLICY source_write ON public.reporting_sources FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.kpi_targets (fiscal_year integer NOT NULL, site text NOT NULL, metric text NOT NULL, target numeric NOT NULL, baseline numeric, PRIMARY KEY(fiscal_year,site,metric));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.kpi_targets TO authenticated;
GRANT ALL ON public.kpi_targets TO service_role;
ALTER TABLE public.kpi_targets ENABLE ROW LEVEL SECURITY;
CREATE POLICY target_read ON public.kpi_targets FOR SELECT TO authenticated USING (public.is_approved());
CREATE POLICY target_write ON public.kpi_targets FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.tracker_records (source_id text PRIMARY KEY, site text NOT NULL, project_id text, optimizely_id text, title text NOT NULL, launched date NOT NULL, completed date, outcome text NOT NULL DEFAULT 'Pending', implemented boolean NOT NULL DEFAULT false, significant boolean NOT NULL DEFAULT false, experiment_type text NOT NULL DEFAULT 'A/B test', notes text NOT NULL DEFAULT '', imported_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.tracker_records TO authenticated;
GRANT ALL ON public.tracker_records TO service_role;
ALTER TABLE public.tracker_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY tracker_read ON public.tracker_records FOR SELECT TO authenticated USING (public.is_approved());
CREATE POLICY tracker_write ON public.tracker_records FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.report_snapshots (source_id text NOT NULL, site text NOT NULL, window_start date NOT NULL, window_end date NOT NULL, payload jsonb NOT NULL, refreshed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(source_id,site,window_start,window_end));
GRANT SELECT ON public.report_snapshots TO authenticated;
GRANT ALL ON public.report_snapshots TO service_role;
ALTER TABLE public.report_snapshots ENABLE ROW LEVEL SECURITY;
CREATE POLICY snapshot_read ON public.report_snapshots FOR SELECT TO authenticated USING (public.is_approved());